# V11 market making — cross-vectors produced by the OFFICIAL Python SDK (hyperliquid-python-sdk) for the action shapes the
# quoting engine adds: batches of post-only orders, batches of cancels (by oid and by cloid), scheduleCancel with and without a
# time, reduce-only batches, each with and without `expiresAfter`, on both networks.
#
# Key: a THROWAWAY key generated at random by this script at each run and written into the output (so that the vectors can be
# re-verified). It never held funds and was never registered anywhere; nothing is sent to any network by this script.
# Run (scratch environment, outside the repository):
#   uv venv /tmp/hl-sdk && uv pip install -p /tmp/hl-sdk hyperliquid-python-sdk==0.24.0
#   /tmp/hl-sdk/bin/python sdk-vectors-mm.gen.py > sdk-vectors-mm.json
import json, secrets
import eth_account
from importlib.metadata import version
from eth_utils import to_hex
from hyperliquid.utils.signing import action_hash, sign_l1_action, order_request_to_order_wire, order_wires_to_order_action
from hyperliquid.utils.types import Cloid

KEY = "0x" + secrets.token_hex(32)
w = eth_account.Account.from_key(KEY)
out = {"sdk": "hyperliquid-python-sdk " + version("hyperliquid-python-sdk"), "key": KEY, "keyNote": "throwaway random key generated by the generator; never funded, never registered",
       "address": w.address.lower(), "l1": []}

def l1(name, action, nonce, expires):
    for mainnet in (True, False):
        sig = sign_l1_action(w, action, None, nonce, expires, mainnet)
        out["l1"].append({"name": name, "action": action, "vaultAddress": None, "nonce": nonce, "expiresAfter": expires,
                          "network": "mainnet" if mainnet else "testnet", "connectionId": to_hex(action_hash(action, None, nonce, expires)), "signature": sig})

def wire(asset, is_buy, sz, px, tif, ro, cloid):
    req = {"coin": "X", "is_buy": is_buy, "sz": sz, "limit_px": px, "reduce_only": ro, "order_type": {"limit": {"tif": tif}}, "cloid": Cloid.from_str(cloid)}
    return order_request_to_order_wire(req, asset)

def cid(n): return "0x" + format(n, "032x")

# 1. one post-only quote
l1("alo bid", order_wires_to_order_action([wire(0, True, 0.00016, 64990.0, "Alo", False, cid(1))]), 1794800000000, 1794800010000)
# 2. a two-sided quote set (BTC mainnet index 0): bid + ask, post-only
two = order_wires_to_order_action([wire(0, True, 0.00016, 64990.0, "Alo", False, cid(2)), wire(0, False, 0.00016, 65010.0, "Alo", False, cid(3))])
l1("alo two-sided batch", two, 1794800000001, 1794800010001)
l1("alo two-sided batch, no expiry", two, 1794800000002, None)
# 3. a ladder: 2 bids + 2 asks on ETH testnet index 4, prices with decimals
ladder = order_wires_to_order_action([wire(4, True, 0.01, 1999.5, "Alo", False, cid(4)), wire(4, True, 0.01, 1998.9, "Alo", False, cid(5)),
                                      wire(4, False, 0.01, 2000.5, "Alo", False, cid(6)), wire(4, False, 0.0125, 2001.1, "Alo", False, cid(7))])
l1("alo ladder of four", ladder, 1794800000003, 1794800010003)
# 4. reduce-only: IOC unwind, and a reduce-only batch
l1("reduce-only ioc", order_wires_to_order_action([wire(0, False, 0.00032, 64900.0, "Ioc", True, cid(8))]), 1794800000004, 1794800010004)
l1("reduce-only batch gtc + ioc", order_wires_to_order_action([wire(5, False, 0.11, 150.25, "Gtc", True, cid(9)), wire(5, False, 0.1, 149.0, "Ioc", True, cid(10))]), 1794800000005, 1794800010005)
# 5. batch cancels
l1("cancel batch by oid", {"type": "cancel", "cancels": [{"a": 0, "o": 601262932710}, {"a": 0, "o": 601262932711}, {"a": 1, "o": 7}]}, 1794800000006, 1794800010006)
l1("cancel batch by cloid", {"type": "cancelByCloid", "cancels": [{"asset": 0, "cloid": Cloid.from_str(cid(2)).to_raw()}, {"asset": 0, "cloid": Cloid.from_str(cid(3)).to_raw()}]}, 1794800000007, 1794800010007)
# 6. dead man's switch — the action of Exchange.schedule_cancel: {"type": "scheduleCancel"} + "time" only when not None
l1("scheduleCancel with time", {"type": "scheduleCancel", "time": 1794800060000}, 1794800000008, 1794800010008)
l1("scheduleCancel with time, no expiry", {"type": "scheduleCancel", "time": 1794800060000}, 1794800000009, None)
l1("scheduleCancel unset", {"type": "scheduleCancel"}, 1794800000010, 1794800010010)

print(json.dumps(out, indent=1))
